    [switch]$Remove,
    [switch]$NoStart,
    [string]$TaskName = "XiaoV Host Services"
)

$ErrorActionPreference = "Stop"
$root = (Resolve-Path (Join-Path $PSScriptRoot "..")).Path
$supervisor = Join-Path $root "tools\xiaov_host_services.py"
$python = Join-Path $root ".kws-venv\Scripts\python.exe"
$pythonw = Join-Path $root ".kws-venv\Scripts\pythonw.exe"
$startup = Join-Path $env:APPDATA "Microsoft\Windows\Start Menu\Programs\Startup"
$shortcutPath = Join-Path $startup "XiaoV Host Services.lnk"

if ($Remove) {
    Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false -ErrorAction SilentlyContinue
    Remove-Item -LiteralPath $shortcutPath -Force -ErrorAction SilentlyContinue
    Write-Host "Removed scheduled task: $TaskName"
    exit 0
}

if (!(Test-Path -LiteralPath $supervisor)) {
    throw "Missing supervisor: $supervisor"
}
if (!(Test-Path -LiteralPath $python)) {
    throw "Missing gateway Python: $python"
}
if (!(Test-Path -LiteralPath $pythonw)) {
    throw "Missing windowless Python: $pythonw"
}

$arguments = '-X utf8 "' + $supervisor + '"'
$action = New-ScheduledTaskAction -Execute $python -Argument $arguments -WorkingDirectory $root
$trigger = New-ScheduledTaskTrigger -AtLogOn
$settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -RestartCount 3 -RestartInterval (New-TimeSpan -Minutes 1)
$principal = New-ScheduledTaskPrincipal -UserId $env:USERNAME -LogonType Interactive -RunLevel Limited

$scheduled = $false
try {
    Register-ScheduledTask -TaskName $TaskName -Action $action -Trigger $trigger -Settings $settings -Principal $principal -Description "Keeps Xiao V production gateway and local Edge TTS available." -Force -ErrorAction Stop | Out-Null
    $scheduled = $true
} catch {
    Write-Warning "Task Scheduler registration was unavailable; using the current-user Startup folder. $($_.Exception.Message)"
}

if ($scheduled -and !$NoStart) {
    Start-ScheduledTask -TaskName $TaskName
}
if (!$scheduled) {
    New-Item -ItemType Directory -Path $startup -Force | Out-Null
    $shell = New-Object -ComObject WScript.Shell
    $shortcut = $shell.CreateShortcut($shortcutPath)
    $shortcut.TargetPath = $pythonw
    $shortcut.Arguments = $arguments
    $shortcut.WorkingDirectory = $root
    $shortcut.WindowStyle = 7
