                / "libs"
                / "ffmpeg"
                / "birds.mp4"
            )
            video_bridge = VideoBridge(
                mqtt=mqtt if mqtt_profile == "greecam_v1" else None,
                topic_prefix=mqtt_topic_prefix,
                device_id=mqtt_device_id,
                desired_fps=args.video_fps,
                local_video_source=(
